SELECT define_provision($q$CHRC_PLANNING_SCHEME_2016@2024-06-07$q$, $q$Table 8.3.5.3.1 PO1 / AO1$q$, 'ACCEPTABLE_OUTCOME', $q$Frontage setbacks for buildings and structures || PO1 Where located in the Rural zone (excluding the Gemfields precincts), a dwelling house is set back from any road frontage to:- maintain an open or mostly open rural landscape; protect the natural rural landscape character and amenity; protect the safe and efficient functioning of the State and local road networks. | AO1 In the Rural zone (excluding the Gemfields precincts) the dwelling house is set back at least:- 100m from a State controlled road frontage; and 20m from any other road frontage.$q$, 'VERIFIED_VERBATIM', $q$ePlan section 215 (8.3.5), rules 10556/10557, revision 82$q$, NULL, $q$Dwelling house code$q$, NULL, $q$https://eplan.chrc.qld.gov.au/planningscheme/rules/0/215/0/0/0/82$q$, $q$Schedule 1 SC1.2.2 "Setback ... means the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is."$q$, $q$chrc_dh_ao1_rural_front$q$);
SELECT define_rule($q${"rule_id": "CHRC.chrc_dh_ao1_rural_front", "instrument_version": "CHRC_PLANNING_SCHEME_2016@2024-06-07", "topic": "SETBACK.FRONTAGE", "title": "Table 8.3.5.3.1 PO1 / AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "Frontage setbacks for buildings and structures || PO1 Where located in the Rural zone (excluding the Gemfields precincts), a dwelling house is set back from any road frontage to:- maintain an open or mostly open rural landscape; protect the natural rural landscape character and amenity; protect the safe and efficient functioning of the State and local road networks. | AO1 In the Rural zone (excluding the Gemfields precincts) the dwelling house is set back at least:- 100m from a State controlled road frontage; and 20m from any other road frontage.", "extracted_value": 20, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2024-06-07", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "CENTRAL_HIGHLANDS"}, {"level": "ZONE", "zone": "CHRC:RURAL"}], "subjects": ["ANY"], "sources": [{"key": "chrc_dh_ao1_rural_front", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"road frontage setback\", \"operator\": \"conditional\", \"value\": 20, \"unit\": \"m\", \"conditions\": [\"State controlled road frontage: >= 100 m\", \"any other road frontage: >= 20 m\"], \"exceptions\": [\"Gemfields Core, Gemfields Frame and Gemfields Balance precincts (see AO2)\"], \"formula_text\": null}\nStructure scope 'dwelling house (use definition includes \"any domestic outbuildings associated with the dwelling\"); table heading: \"buildings and structures\"' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES - Table 1.6.1: \"Alternative provisions to QDC part MP1.2 road boundary setbacks | Section 8.3.5 Dwelling house code PO1 and AO1; PO2 and AO2\"; code editor's note: \"AO1 and AO2 are alternative provisions to A1 of QDC part 1.2.\"\nResearcher notes: AO text says \"the dwelling house\"; the table row heading is \"Frontage setbacks for buildings and structures\", the scheme definition of Dwelling house includes associated domestic outbuildings, and the code note says it applies to \"associated Class 10 domestic outbuildings and structures\". Treated as reaching Class 10a; curator to confirm. Table 5.6.1 makes a Class 10a building in the Rural zone (excl. Gemfields) accepted development with no requirements, but AO1 is still a building assessment provision (Table 1.6.1) applied by the building certifier. Precinct exclusion cannot be expressed in raw_scopes (scoped to whole RURAL zone; Gemfields precincts covered by chrc_dh_ao2_gemfields_front)."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CHRC.chrc_dh_ao1_rural_front@2024-06-07$q$;
