INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CHRC.chrc_dh_ao1_rural_front@2024-06-07$q$, $q$QDC11.A1a.FRONTAGE_SETBACK$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CHRC_PLANNING_SCHEME_2016@2024-06-07$q$, $q$Table 8.3.5.3.1 PO2 / AO2$q$, 'ACCEPTABLE_OUTCOME', $q$Frontage setbacks for buildings and structures || PO2 Where located in the Rural zone in a Gemfields precinct, a dwelling house is sufficiently set back from any road frontage to complement the individuality and unconventional form and style of the area. Editor’s note—PO1 and PO2 are alternative provisions to P1 of QDC part 1.2. | AO2 In the Rural zone in a Gemfields precinct the dwelling house is set back:- 10m from the frontage where on a lot greater than 1,000m2; or 6m from the frontage where on a lot 1,000m2 or less. Editor’s note—AO1 and AO2 are alternative provisions to A1 of QDC part 1.2.$q$, 'VERIFIED_VERBATIM', $q$ePlan section 215 (8.3.5), rule 10559, revision 82$q$, NULL, $q$Dwelling house code$q$, NULL, $q$https://eplan.chrc.qld.gov.au/planningscheme/rules/0/215/0/0/0/82$q$, $q$Schedule 1 SC1.2.2 "Setback" definition (measured horizontally to outermost projection).$q$, $q$chrc_dh_ao2_gemfields_front$q$);
SELECT define_rule($q${"rule_id": "CHRC.chrc_dh_ao2_gemfields_front", "instrument_version": "CHRC_PLANNING_SCHEME_2016@2024-06-07", "topic": "SETBACK.FRONTAGE", "title": "Table 8.3.5.3.1 PO2 / AO2", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "Frontage setbacks for buildings and structures || PO2 Where located in the Rural zone in a Gemfields precinct, a dwelling house is sufficiently set back from any road frontage to complement the individuality and unconventional form and style of the area. Editor’s note—PO1 and PO2 are alternative provisions to P1 of QDC part 1.2. | AO2 In the Rural zone in a Gemfields precinct the dwelling house is set back:- 10m from the frontage where on a lot greater than 1,000m2; or 6m from the frontage where on a lot 1,000m2 or less. Editor’s note—AO1 and AO2 are alternative provisions to A1 of QDC part 1.2.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2024-06-07", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "CENTRAL_HIGHLANDS"}, {"level": "PRECINCT", "precinct": "CHRC:RURAL/GEMFIELDS_CORE"}, {"level": "PRECINCT", "precinct": "CHRC:RURAL/GEMFIELDS_FRAME"}, {"level": "PRECINCT", "precinct": "CHRC:RURAL/GEMFIELDS_BALANCE"}], "subjects": ["ANY"], "sources": [{"key": "chrc_dh_ao2_gemfields_front", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"road frontage setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"lot area > 1,000 m2: 10 m from the frontage\", \"lot area <= 1,000 m2: 6 m from the frontage\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): lot > 1,000 m2: 10 m; lot <= 1,000 m2: 6 m\nStructure scope 'dwelling house (use definition includes \"any domestic outbuildings associated with the dwelling\"); table heading: \"buildings and structures\"' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES - Table 1.6.1 lists \"Section 8.3.5 Dwelling house code PO1 and AO1; PO2 and AO2\" as \"Alternative provisions to QDC part MP1.2 road boundary setbacks\"; editor's note: \"AO1 and AO2 are alternative provisions to A1 of QDC part 1.2.\"\nResearcher notes: AO wording is \"set back\" (not \"at least\"); read as a minimum per the QDC A1 it replaces, but a curator should confirm. Same dwelling-house-includes-outbuildings scope question as AO1. Gemfields Class 10a buildings are accepted development subject to requirements (AO11.1, AO11.2, AO12.1, AO12.2) under Table 5.6.1."}$q$::jsonb);
