SELECT define_provision($q$CHRC_PLANNING_SCHEME_2016@2024-06-07$q$, $q$Table 8.3.5.3.1 PO3 / AO3$q$, 'ACCEPTABLE_OUTCOME', $q$Side and rear boundary clearances for buildings and structures || PO3 Where located in the Rural zone (excluding the Gemfields precincts), the dwelling house is set back from side and rear boundaries to:- preserve the low intensity character and amenity of the Rural zone; and maintain separation and privacy between neighbouring rural premises. Editor’s note—PO3 is an alternative provision to P2 of QDC part 1.2. | AO3 In the Rural zone (excluding the Gemfields precincts) the dwelling house is set back from any side or rear boundary a minimum of:- 10m on a lot of more than 1 hectare; or 3m on a lot of 1 hectare or less. Editor’s note—AO3 is an alternative provision to A2 of QDC part 1.2.$q$, 'VERIFIED_VERBATIM', $q$ePlan section 215 (8.3.5), rules 10558/10560, revision 82$q$, NULL, $q$Dwelling house code$q$, NULL, $q$https://eplan.chrc.qld.gov.au/planningscheme/rules/0/215/0/0/0/82$q$, $q$Schedule 1 SC1.2.2 "Boundary clearance" and "Setback" definitions (closest part of building, excluding architectural/ornamental attachments and rainwater fittings).$q$, $q$chrc_dh_ao3_rural_side_rear$q$);
SELECT define_rule($q${"rule_id": "CHRC.chrc_dh_ao3_rural_side_rear", "instrument_version": "CHRC_PLANNING_SCHEME_2016@2024-06-07", "topic": "SETBACK.SIDE", "title": "Table 8.3.5.3.1 PO3 / AO3", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "Side and rear boundary clearances for buildings and structures || PO3 Where located in the Rural zone (excluding the Gemfields precincts), the dwelling house is set back from side and rear boundaries to:- preserve the low intensity character and amenity of the Rural zone; and maintain separation and privacy between neighbouring rural premises. Editor’s note—PO3 is an alternative provision to P2 of QDC part 1.2. | AO3 In the Rural zone (excluding the Gemfields precincts) the dwelling house is set back from any side or rear boundary a minimum of:- 10m on a lot of more than 1 hectare; or 3m on a lot of 1 hectare or less. Editor’s note—AO3 is an alternative provision to A2 of QDC part 1.2.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2024-06-07", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "CENTRAL_HIGHLANDS"}, {"level": "ZONE", "zone": "CHRC:RURAL"}], "subjects": ["ANY"], "sources": [{"key": "chrc_dh_ao3_rural_side_rear", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"side and rear boundary setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"applies to side AND rear boundaries\", \"lot area > 1 ha: >= 10 m\", \"lot area <= 1 ha: >= 3 m\"], \"exceptions\": [\"Gemfields Core, Gemfields Frame and Gemfields Balance precincts\"], \"formula_text\": null}\nLot conditions (not encoded): lot > 1 ha: 10 m; lot <= 1 ha: 3 m\nStructure scope 'dwelling house (use definition includes \"any domestic outbuildings associated with the dwelling\"); table heading: \"buildings and structures\"' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES - Table 1.6.1: \"Alternative provisions to QDC part MP1.2 side and rear boundary clearances | Section 8.3.5 Dwelling house code PO3 and AO3\"; editor's note: \"AO3 is an alternative provision to A2 of QDC part 1.2.\"\nResearcher notes: No height banding. Same scope question as AO1 (AO says \"the dwelling house\"; heading says \"buildings and structures\"; Dwelling house definition includes domestic outbuildings)."}$q$::jsonb);
