INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$CENTRAL_HIGHLANDS$q$, $q$CHRC_PLANNING_SCHEME_2016$q$, 'MEDIUM', $q$Do Dwelling house code AO1-AO3 (worded "the dwelling house") reach detached Class 10a outbuildings? Headings say "buildings and structures", the use definition of Dwelling house includes domestic outbuildings, and the code note says it applies to associated Class 10 domestic outbuildings - treated as in scope, needs curator confirmation.$q$);
